nts/product-faq\",\"__typename\":\"TwoColumnContainerModel\",\"onDark\":false,\"colorBackground\":\"base\",\"componentWidth\":\"pageWidth\",\"gridConfiguration\":\"40-60\",\"mobileView\":\"leftOnTop\",\"addColumnGap\":true,\"twoColumnGridLeftComponent\":{\"__typename\":\"BasicTextModel\",\"_path\":\"/content/dam/ggp/goodyear/consumer/na/en-US/products/services/211130/components/includes/product-faq-left-content\",\"eyebrow\":\"COMMON BATTERY INSPECTION AND REPLACEMENT QUESTIONS\",\"headline\":\"Looking for assistance?\",\"subtitle\":null,\"divider\":false,\"headingTag\":\"h2\",\"onDark\":null,\"componentWidth\":\"fullBleed\",\"headlineSize\":\"medium\",\"description\":{\"html\":null}},\"twoColumnGridRightComponent\":{\"__typename\":\"AccordionContainerModel\",\"_path\":\"/content/dam/ggp/goodyear/consumer/na/en-US/products/services/211130/components/includes/product-faq-right-content\",\"subtitle\":null,\"buttonLabel\":null,\"buttonUrl\":null,\"buttonAction\":\"sameTab\",\"buttonAccessibilityLabel\":null,\"onDark\":null,\"componentWidth\":\"fullBleed\",\"divider\":false,\"accordionItems\":[{\"__typename\":\"AccordionItemModel\",\"_path\":\"/content/dam/ggp/goodyear/consumer/na/en-US/products/services/211130/components/includes/faq-items/how-long-do-car-batteries-last\",\"eyebrow\":null,\"title\":\"How Long do Car Batteries Last?\",\"description\":{\"html\":\"\u003cp\u003eThe life of your vehicle’s battery depends on its ability to hold a charge, as well as its ability to be recharged. There are several factors that may affect your battery life, including humidity, temperature, and other environmental factors. On average, batteries last 55 months *\u003c/p\u003e\u003cp\u003e*Battery Council International Technical Subcommittee Study Report in 2010\u003c/p\u003e\u003cp\u003e\u003c/p\u003e\"}},{\"__typename\":\"AccordionItemModel\",\"_path\":\"/content/dam/ggp/goodyear/consumer/na/en-US/products/services/211130/components/includes/faq-items/what-drains-a-car-battery\",\"eyebrow\":null,\"title\":\"What Drains a Car Battery?\",\"description\":{\"html\":\"\u003cp\u003eThere are several ways your vehicle’s battery can drain, including leaving your lights on, a bad alternator, and age can also be a factor.\u003c/p\u003e\u003cp\u003e\u003c/p\u003e\"}},{\"__typename\":\"AccordionItemModel\",\"_path\":\"/content/dam/ggp/goodyear/consumer/na/en-US/products/services/211130/components/includes/faq-items/what-size-car-battery-do-i-need\",\"eyebrow\":null,\"title\":\"What Size Car Battery Do I Need?\",\"description\":{\"html\":\"\u003cp\u003eYour vehicle’s battery size falls into one of several groups, and is determined by the year, make, model and engine size of your vehicle. If you are unsure of your vehicle’s battery requirements, check your vehicle manual or talk to one of our technicians for the original equipment (OE) manufacturer’s recommendations.\u003c/p\u003e\u003cp\u003e\u003c/p\u003e\"}},{\"__typename\":\"AccordionItemModel\",\"_path\":\"/content/dam/ggp/goodyear/consumer/na/en-US/products/services/211130/components/includes/faq-items/how-many-volts-is-a-car-battery\",\"eyebrow\":null,\"title\":\"How Many Volts is a Car Battery?\",\"description\":{\"html\":\"\u003cp\u003eMost vehicles have 12-volt electrical systems, but there are some (like hybrid/electric vehicles) that are highly electrified and use higher voltage systems. Some older vehicles used less than 12-volt systems as well.\u003c/p\u003e\u003cp\u003e\u003c/p\u003e\"}},{\"__typename\":\"AccordionItemModel\",\"_path\":\"/content/dam/ggp/goodyear/consumer/na/en-US/products/services/211130/components/includes/faq-items/how-to-test-a-car-battery\",\"eyebrow\":null,\"title\":\"How to Test a Car Battery?\",\"description\":{\"html\":\"\u003cp\u003eTesting an existing battery is critical to determining the remaining voltage left in the battery.\u003c/p\u003e\u003cp\u003e\u003c/p\u003e\"}},{\"__typename\":\"AccordionItemModel\",\"_path\":\"/content/dam/ggp/goodyear/consumer/na/en-US/products/services/211130/components/includes/faq-items/how-to-use-a-multimeter-to-test-a-car-battery\",\"eyebrow\":null,\"title\":\"How to Use a Multimeter to Test a Car Battery?\",\"description\":{\"html\":\"\u003cp\u003eYou can test your vehicle’s battery by using a multimeter, which tells you the voltage of your battery. Fully charged batteries should measure at 12.6 volts or above. When the engine is running, this measurement should be 13.7 to 14.7 volts.\u003c/p\u003e\u003cp\u003eIf you are uncertain about how your battery is performing, please visit one of our locations for a battery inspection today.\u003c/p\u003e\u003cp\u003e\u003c/p\u003e\"}},{\"__typename\":\"AccordionItemModel\",\"_path\":\"/content/dam/ggp/goodyear/consumer/na/en-US/products/services/211130/components/includes/faq-items/how-to-tell-if-a-car-battery-is-bad\",\"eyebrow\":null,\"title\":\"How to Tell if a Car Battery is Bad?\",\"description\":{\"html\":\"\u003cp\u003eThere are telltale signs that can point to a bad battery. If you experience one of the following items, bring your vehicle contact and bring your car into one of our locations as soon as possible.\u003c/p\u003e\\n\u003cp\u003eSigns a Car Battery is Going Bad:\u003c/p\u003e\u003cp\u003e\\n\u003c/p\u003e\u003cul\u003e \u003cli\u003eSlowly Starting Car: Upon ignition, listen for the engine to be struggling to turn over.\u003c/li\u003e \u003cli\u003eIlluminated Indicator Lights: Watch if the dashboard lights indicating the car’s charging system will be on at the time of ignition.\u003c/li\u003e\\n\u003c/ul\u003e\u003cp\u003e\u003c/p\u003e\"}},{\"__typename\":\"AccordionItemModel\",\"_path\":\"/content/dam/ggp/goodyear/consumer/na/en-US/products/services/211130/components/includes/faq-items/how-to-clean-car-battery-terminals\",\"eyebrow\":null,\"title\":\"How to Clean Car Battery Terminals?\",\"description\":{\"html\":\"\u003cp\u003eWe recommend letting our professionals help you with your car battery, so schedule a battery service appointment at one of our locations if you think your battery is in need of a cleaning.\u003c/p\u003e\u003cp\u003e\u003c/p\u003e\"}},{\"__typename\":\"AccordionItemModel\",\"_path\":\"/content/dam/ggp/goodyear/consumer/na/en-US/products/services/211130/components/includes/faq-items/how-to-charge-a-car-battery\",\"eyebrow\":null,\"title\":\"How to Charge a Car Battery?\",\"description\":{\"html\":\"\u003cp\u003eWe recommend letting our technicians help you with your car battery, so schedule an appointment at one of our locations if you think your battery is in need of a charge.\u003c/p\u003e\u003cp\u003e\u003c/p\u003e\"}}]}}]}}},\"errors\":null,\"metadata\":{\"usid\":\"98dedae1-ba10-4139-a8cf-75409beed7ce\"}}},\"dataUpdateCount\":1,\"dataUpdatedAt\":1779658201809,\"error\":null,\"errorUpdateCount\":0,\"errorUpdatedAt\":0,\"fetchFailureCount\":0,\"fetchFailureReason\":null,\"fetchMeta\":null,\"isInvalidated\":false,\"status\":\"success\",\"fetchStatus\":\"idle\"},\"queryKey\":[\"product-faq\",\"211130\",\"products/services/211130/product-faq\"],\"queryHash\":\"[\\\"product-faq\\\",\\\"211130\\\",\\\"products/services/211130/product-faq\\\"]\"},{\"dehydratedAt\":1779658201809,\"state\":{\"data\":{\"_path\":\"/content/dam/ggp/goodyear/consumer/na/en-US/pages/services/product/product\",\"__typename\":\"PageModel\",\"_metadata\":{\"calendarMetadata\":[{\"name\":\"jcr:created\",\"value\":\"2026-02-19T21:42:56.087Z\"},{\"name\":\"cq:lastPublished\",\"value\":\"2026-04-02T16:46:40.369Z\"},{\"name\":\"cq:lastModified\",\"value\":\"2026-04-14T15:19:56.120Z\"},{\"name\":\"cq:lastRolledout\",\"value\":\"2026-04-09T13:07:39.386Z\"}]},\"name\":\"PDP\",\"pageTitle\":\"Auto Services | Auto Repair Services\",\"description\":\"Browse the wide range of professional auto services offered by Goodyear. From oil changes to engine repair, rely on us for expert vehicle repair services.\",\"keywords\":null,\"categoryTags\":null,\"templateType\":\"Services\",\"canonicalUrl\":\"/content/dam